package fetvisuals.modules.effects;
import fetvisuals.module.*; import fetvisuals.module.settings.*; import fetvisuals.render.RenderUtils; import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.DrawContext;
public final class LowHealthVignette extends fetvisuals.module.Module {private final NumberSetting threshold=add(new NumberSetting("Threshold",5,1,20,.5));private final NumberSetting intensity=add(new NumberSetting("Intensity",90,0,180,1));public LowHealthVignette(){super("LowHealthVignette","Purple low-health screen effect",Category.EFFECTS);}public void onHud(DrawContext c,float d){MinecraftClient mc=MinecraftClient.getInstance();if(mc.player==null||mc.player.getHealth()>threshold.get())return;float p=1-mc.player.getHealth()/(float)Math.max(1,threshold.get());int a=(int)(intensity.get()*p);int col=RenderUtils.alpha(0xA11BFF,a);int w=mc.getWindow().getScaledWidth(),h=mc.getWindow().getScaledHeight();RenderUtils.rect(c,0,0,w,8,col);RenderUtils.rect(c,0,h-8,w,8,col);RenderUtils.rect(c,0,0,8,h,col);RenderUtils.rect(c,w-8,0,8,h,col);}}
